FILES = {'level1.py': '"""Level-1 scan: can a fix-up block with >= 1.0 expected Toffolis be paid by ONE conditioned CCZ on affine\nforms (L1, L2, L3) at some window position plus free Z / CZ terms anywhere in the window?\n\nF + L1*L2*L3 in span(M), M = union of quadratic forms over the window (see scan0.py).\nL1, L3 range over weight <= 2 forms of a relevant qubit set R; L2 is solved exactly (it enters linearly).\nMembership is tested with K random parity checks of span(M) (syndromes), then re-checked on full vectors.\n\nUsage: python level1.py CIRCUIT.kmx [--before 12] [--after 12] [--min 1.0] [--lines a,b,...]\n"""\nimport argparse, itertools, sys, time\nimport numpy as np\nfrom bitsim import parse, unpack, pack\nfrom blockpoly import touched\nfrom scan0 import prepare, window, reduce_in_span, lowbit_index, FULL\n\nPOP8 = np.array([bin(i).count("1") for i in range(256)], dtype=np.uint8)\n\n\ndef parity_rows(A):\n    """A: (..., W) uint64 -> parity bit of each row."""\n    v = np.bitwise_xor.reduce(A, axis=-1)\n    v ^= v >> np.uint64(32); v ^= v >> np.uint64(16); v ^= v >> np.uint64(8)\n    v ^= v >> np.uint64(4); v ^= v >> np.uint64(2); v ^= v >> np.uint64(1)\n    return (v & np.uint64(1)).astype(np.uint8)\n\n\ndef rref(M):\n    M = M.copy()\n    C = M.shape[0]\n    piv = []\n    for r in range(C):\n        p = lowbit_index(M[r])\n        if p < 0:\n            continue\n        wi, bi = p // 64, np.uint64(p % 64)\n        sel = ((M[:, wi] >> bi) & np.uint64(1)).astype(bool)\n        sel[r] = False\n        M[sel] ^= M[r]\n        piv.append((r, p))\n    return M, piv\n\n\ndef null_checks(M, K, rng):\n    R, piv = rref(M)\n    W = M.shape[1]\n    H = np.zeros((K, W), dtype=np.uint64)\n    pmask = np.zeros(W, dtype=np.uint64)\n    for r, p in piv:\n        pmask[p // 64] |= np.uint64(1) << np.uint64(p % 64)\n    for k in range(K):\n        h = rng.integers(0, 2**63, size=W, dtype=np.uint64) * np.uint64(2) + rng.integers(0, 2, size=W, dtype=np.uint64)\n        h &= ~pmask\n        rows = np.array([R[r] for r, p in piv])\n        bits = parity_rows(rows & h[None, :])\n        for (r, p), b in zip(piv, bits):\n            if b:\n                h[p // 64] |= np.uint64(1) << np.uint64(p % 64)\n        H[k] = h\n    assert not parity_rows(M[:, None, :] & H[None, :, :]).any(), "null check failed"\n    return H\n\n\ndef syndromes(V, H):\n    """V (N, W), H (K, W) -> (N, K//64) uint64 packed syndromes."""\n    K = H.shape[0]\n    out = np.zeros((V.shape[0], K // 64), dtype=np.uint64)\n    for k in range(K):\n        b = parity_rows(V & H[k][None, :]).astype(np.uint64)\n        out[:, k // 64] |= b << np.uint64(k % 64)\n    return out\n\n\ndef batched_member(A, s):\n    """A (N, m, KW) syndromes of m generators per system, s (KW,) target. -> bool (N,) s in span(A[n])."""\n    N, m, KW = A.shape\n    X = np.concatenate([A, np.broadcast_to(s, (N, 1, KW))], axis=1).copy()\n    used = np.zeros((N, m), dtype=bool)\n    ar = np.arange(N)\n    for k in range(KW * 64):\n        w, bit = k // 64, np.uint64(k % 64)\n        colbits = ((X[:, :, w] >> bit) & np.uint64(1)).astype(bool)\n        has = colbits[:, :m] & ~used\n        anyp = has.any(1)\n        if not anyp.any():\n            continue\n        piv = np.argmax(has, 1)\n        prow = X[ar, piv]\n        sel = colbits & anyp[:, None]\n        sel[ar[anyp], piv[anyp]] = False\n        used[ar[anyp], piv[anyp]] = True\n        X ^= np.where(sel[:, :, None], prow[:, None, :], np.uint64(0))\n    return ~X[:, m, :].any(1)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("circuit")\n    ap.add_argument("--before", type=int, default=12)\n    ap.add_argument("--after", type=int, default=12)\n    ap.add_argument("--min", type=float, default=1.0)\n    ap.add_argument("--nrand", type=int, default=4096)\n    ap.add_argument("--K", type=int, default=128)\n    ap.add_argument("--lines", default=None)\n    ap.add_argument("--rmax", type=int, default=14)\n    a = ap.parse_args()\n    nq, body, hdr, xs, W, snaps, snap_idx, blocks = prepare(a.circuit, a.nrand, a.min)\n    want = None if a.lines is None else {int(v) for v in a.lines.split(",")}\n    rng = np.random.default_rng(7)\n    for rec in blocks:\n        if want is not None and rec["line"] not in want:\n            continue\n        tag = f"line {rec[\'line\']} cond {rec[\'cond\']} tof {rec[\'tof\']}"\n        if not rec.get("neutral") or not rec.get("gf2") or rec["bitfx"]:\n            print(tag, "SKIP"); continue\n        t0 = time.time()\n        F = rec["F"]\n        rows, labels, states, nb, na = window(nq, W, snaps, snap_idx, rec, a.before, a.after)\n        M = np.array(rows)\n        H = null_checks(M, a.K, rng)\n        sF = syndromes(F[None, :], H)[0]\n        tq = touched(body, rec["i"], rec["j"])\n        # relevant set: block\'s touched qubits + targets of nearby events\n        near = []\n        for k in range(max(0, rec["snap_before"] - 4), min(len(snaps), rec["snap_before"] + 4)):\n            if snaps[k][1] in ("CCX", "CSWAP"):\n                near += snaps[k][2]\n        R = []\n        for q in tq + near:\n            if q not in R:\n                R.append(q)\n        R = R[: a.rmax]\n        hits = []\n        for (pidx, st) in states:\n            live = [q for q in range(nq) if st[q].any()]\n            Rl = [q for q in R if st[q].any()]\n            if len(Rl) < 2:\n                continue\n            forms = [(q,) for q in Rl] + list(itertools.combinations(Rl, 2))\n            gens = [None] + live  # b = const or a live qubit\n            # T[a][c] -> syndromes over gens\n            vec = {}\n            idx = {q: t for t, q in enumerate(Rl)}\n            pairs = [(x, y) for x in range(len(Rl)) for y in range(x, len(Rl))]\n            V = []\n            for (x, y) in pairs:\n                base = st[Rl[x]] & st[Rl[y]]\n                for g in gens:\n                    V.append(base if g is None else base & st[g])\n            Sy = syndromes(np.array(V), H).reshape(len(pairs), len(gens), -1)\n            Tm = np.zeros((len(Rl), len(Rl), len(gens), Sy.shape[2]), dtype=np.uint64)\n            for t, (x, y) in enumerate(pairs):\n                Tm[x, y] = Sy[t]; Tm[y, x] = Sy[t]\n            combos = []\n            A = []\n            for i1 in range(len(forms)):\n                for i3 in range(i1, len(forms)):\n                    acc = np.zeros((len(gens), Sy.shape[2]), dtype=np.uint64)\n                    for u in forms[i1]:\n                        for v in forms[i3]:\n                            acc ^= Tm[idx[u], idx[v]]\n                    A.append(acc); combos.append((forms[i1], forms[i3]))\n            A = np.array(A)\n            ok = batched_member(A, sF)\n            for t in np.flatnonzero(ok):\n                L1, L3 = combos[t]\n                # exact re-check on full sample vectors\n                l1 = np.bitwise_xor.reduce(np.array([st[q] for q in L1]), axis=0)\n                l3 = np.bitwise_xor.reduce(np.array([st[q] for q in L3]), axis=0)\n                extra = [l1 & l3] + [l1 & l3 & st[g] for g in live]\n                good, _ = reduce_in_span(np.concatenate([M, np.array(extra)]), F)\n                if good:\n                    hits.append((pidx + hdr + 1, L1, L3))\n        print(tag, "states", len(states), "R", R, "hits", len(hits), hits[:6], f"{time.time()-t0:.1f}s", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'bitsim.py': '"""Bit-packed classical simulator for invsqrt .kmx netlists (our own code; no third-party code runs).\n\nState: one uint64 word per 64 shots for every qubit; classical bits likewise; a GF(2) phase word\n(Z / CZ / CCZ / NEG / HMR kickback; Z_POW rotations are ignored). Conditions (PUSH_CONDITION and\n"... if bN") mask every effect. HMR draws a random outcome m, adds m*q to the phase and resets q.\n\nparse(path) -> (nq, body) with body a list of (op, args tuple, cond_bit or None).\nSim(nq, xs, seed).run(body, lo, hi, hook) executes lines lo..hi-1; hook(i, sim) is called before each line.\n"""\nimport numpy as np\n\nMAX_X = 3 * (2**10 - 2) ** 2\nFULL = np.uint64(0xFFFFFFFFFFFFFFFF)\nTOF = {"CCX", "CCZ", "CSWAP"}\n\n\ndef parse(path):\n    nq = 0\n    body = []\n    for raw in open(path):\n        l = raw.strip()\n        if not l or l.startswith("#"):\n            continue\n        t = l.split()\n        if t[0] == "APPEND_TO_REGISTER":\n            nq = max(nq, int(t[1][1:]) + 1)\n            continue\n        if t[0] == "REGISTER":\n            continue\n        cond = None\n        if len(t) >= 3 and t[-2] == "if":\n            cond = t[-1]\n            t = t[:-2]\n        op = t[0]\n        if op == "PUSH_CONDITION":\n            body.append((op, (), cond))\n            continue\n        args = []\n        for a in t[1:]:\n            if a[0] == "q":\n                args.append(int(a[1:]))\n                nq = max(nq, int(a[1:]) + 1)\n            elif a[0] == "b":\n                args.append(a)\n            else:\n                args.append(a)\n        body.append((op, tuple(args), cond))\n    return nq, body\n\n\ndef edge_and_random(n_random, seed=5):\n    p2 = {v for k in range(23) for v in (2**k - 1, 2**k, 2**k + 1) if 1 <= v <= MAX_X} | {MAX_X, MAX_X - 1}\n    edge = sorted(set(range(1, 4097)) | p2 | {4 * v for v in range(1, 1024)})\n    edge = [v for v in edge if v <= MAX_X]\n    rng = np.random.default_rng(seed)\n    xs = np.concatenate([np.array(edge, dtype=np.uint64),\n                         rng.integers(1, MAX_X + 1, size=n_random, dtype=np.uint64)])\n    pad = (-len(xs)) % 64\n    if pad:\n        xs = np.concatenate([xs, rng.integers(1, MAX_X + 1, size=pad, dtype=np.uint64)])\n    return xs\n\n\ndef pack(boolrows):\n    """bool array (k, S) -> uint64 (k, S/64), shot s at bit s%64 of word s//64."""\n    b = np.asarray(boolrows, dtype=bool)\n    k, S = b.shape\n    return np.packbits(b.reshape(k, S // 64, 64)[:, :, ::-1], axis=2).view(">u8").astype(np.uint64).reshape(k, S // 64)\n\n\ndef unpack(words):\n    w = np.ascontiguousarray(np.atleast_2d(words).astype(">u8"))\n    k, W = w.shape\n    return np.unpackbits(w.view(np.uint8).reshape(k, W, 8), axis=2).reshape(k, W, 64)[:, :, ::-1].reshape(k, W * 64).astype(bool)\n\n\nclass Sim:\n    def __init__(self, nq, xs, seed=1):\n        self.S = len(xs)\n        assert self.S % 64 == 0\n        self.W = self.S // 64\n        self.nq = nq\n        self.q = np.zeros((nq, self.W), dtype=np.uint64)\n        bits = (xs[None, :] >> np.arange(22, dtype=np.uint64)[:, None]) & np.uint64(1)\n        self.q[:22] = pack(bits == 1)\n        self.b = {}\n        self.ph = np.zeros(self.W, dtype=np.uint64)\n        self.ph8 = np.zeros(self.S, dtype=np.int64)  # dyadic Z_POW phases, units of 1/8 turn\n        self.rng = np.random.default_rng(seed)\n        self.stack = [np.full(self.W, FULL, dtype=np.uint64)]\n        self.force = {}\n        self.tof = 0  # bit name -> forced word (used to force a condition to 1)\n\n    def bit(self, name):\n        if name in self.force:\n            return self.force[name]\n        return self.b.get(name, np.zeros(self.W, dtype=np.uint64))\n\n    def mask(self, cond):\n        m = self.stack[-1]\n        if cond is not None:\n            m = m & self.bit(cond)\n        return m\n\n    def step(self, op, a, cond):\n        q = self.q\n        if op == "PUSH_CONDITION":\n            self.stack.append(self.mask(cond))\n            return\n        if op == "POP_CONDITION":\n            self.stack.pop()\n            return\n        m = self.mask(cond)\n        if op in TOF:\n            self.tof += int(popcount_rows(m))\n        if op == "CX":\n            q[a[1]] ^= q[a[0]] & m\n        elif op == "CCX":\n            q[a[2]] ^= q[a[0]] & q[a[1]] & m\n        elif op == "X":\n            q[a[0]] ^= m\n        elif op == "Z":\n            self.ph ^= q[a[0]] & m\n        elif op == "CZ":\n            self.ph ^= q[a[0]] & q[a[1]] & m\n        elif op == "CCZ":\n            self.ph ^= q[a[0]] & q[a[1]] & q[a[2]] & m\n        elif op == "NEG":\n            self.ph ^= m\n        elif op == "SWAP":\n            i, j = a\n            d = (q[i] ^ q[j]) & m\n            q[i] ^= d\n            q[j] ^= d\n        elif op == "CSWAP":\n            c, i, j = a\n            d = (q[i] ^ q[j]) & q[c] & m\n            q[i] ^= d\n            q[j] ^= d\n        elif op == "HMR":\n            t, bn = a\n            r = self.rng.integers(0, 2**63, size=self.W, dtype=np.uint64) * np.uint64(2) + \\\n                self.rng.integers(0, 2, size=self.W, dtype=np.uint64)\n            self.ph ^= r & q[t] & m\n            q[t] &= ~m\n            old = self.b.get(bn, np.zeros(self.W, dtype=np.uint64))\n            self.b[bn] = (old & ~m) | (r & m)\n        elif op == "BIT_STORE0":\n            bn = a[0]\n            old = self.b.get(bn, np.zeros(self.W, dtype=np.uint64))\n            self.b[bn] = old & ~m\n        elif op == "BIT_STORE1":\n            bn = a[0]\n            old = self.b.get(bn, np.zeros(self.W, dtype=np.uint64))\n            self.b[bn] = old | m\n        elif op == "BIT_INVERT":\n            bn = a[0]\n            old = self.b.get(bn, np.zeros(self.W, dtype=np.uint64))\n            self.b[bn] = old ^ m\n        elif op == "Z_POW":\n            k = float(a[1]) * 4\n            if abs(k - round(k)) < 1e-9:\n                bits = unpack((q[a[0]] & m)[None, :])[0]\n                self.ph8 = (self.ph8 + int(round(k)) * bits.astype(np.int64)) % 8\n        else:\n            raise ValueError(op)\n\n    def run(self, body, lo=0, hi=None, hook=None):\n        hi = len(body) if hi is None else hi\n        for i in range(lo, hi):\n            if hook is not None:\n                hook(i, self)\n            op, a, c = body[i]\n            self.step(op, a, c)\n\n\ndef phase8(sim):\n    return (4 * unpack(sim.ph[None, :])[0].astype(np.int64) + sim.ph8) % 8\n\n\ndef popcount_rows(w):\n    return np.unpackbits(np.ascontiguousarray(w).view(np.uint8), axis=-1).sum(axis=-1)\n', 'blockpoly.py': '"""Exact phase polynomial of conditioned fix-up blocks.\n\nFor a top-level PUSH_CONDITION block (lines i..j), take its inputs = qubits it touches that are not zero at\nentry on the sample; simulate the block (outer condition forced to 1, nested HMR outcomes random) on all\n2^k assignments of those inputs with every other touched qubit at 0. Returns the phase (units of 1/8 turn)\nand, if it is a +/-1 phase, its GF(2) ANF as a set of monomials (tuples of qubit ids).\n"""\nimport itertools\nimport numpy as np\nfrom bitsim import Sim, TOF, unpack, phase8\n\n\ndef block_end(body, i):\n    d = 0\n    for j in range(i, len(body)):\n        op = body[j][0]\n        if op == "PUSH_CONDITION":\n            d += 1\n        elif op == "POP_CONDITION":\n            d -= 1\n            if d == 0:\n                return j\n    raise ValueError\n\n\ndef touched(body, i, j):\n    qs = []\n    for op, a, c in body[i:j + 1]:\n        for x in a:\n            if isinstance(x, int) and x not in qs:\n                qs.append(x)\n    return qs\n\n\ndef block_tof(body, i, j):\n    """expected Toffoli-like count of the block assuming each condition level halves (outer included)."""\n    d = 0\n    t = 0.0\n    for op, a, c in body[i:j + 1]:\n        if op == "PUSH_CONDITION":\n            d += 1\n            continue\n        if op == "POP_CONDITION":\n            d -= 1\n            continue\n        if op in TOF:\n            t += 0.5 ** (d + (c is not None))\n    return t\n\n\ndef cube_phase(nq, body, i, j, inputs, seeds=(1, 2)):\n    """phase8 of the block for every assignment of `inputs` (others 0). Returns (phase array, restored?)."""\n    k = len(inputs)\n    n = 1 << k\n    S = max(64, ((n + 63) // 64) * 64)\n    out = []\n    restored = True\n    for seed in seeds:\n        sim = Sim(nq, np.ones(S, dtype=np.uint64), seed)\n        sim.q[:] = 0\n        assign = np.array([[(v >> t) & 1 for v in range(S)] for t in range(k)], dtype=bool)\n        from bitsim import pack\n        P = pack(assign)\n        for t, qq in enumerate(inputs):\n            sim.q[qq] = P[t]\n        before = sim.q.copy()\n        cond = body[i][2]\n        sim.force[cond] = np.full(sim.W, np.uint64(0xFFFFFFFFFFFFFFFF), dtype=np.uint64)\n        # other condition bits used inside (nested) are produced inside the block by HMR\n        sim.run(body, i, j + 1)\n        restored &= np.array_equal(before, sim.q)\n        out.append(phase8(sim)[:n])\n    same = all(np.array_equal(out[0], o) for o in out[1:])\n    return out[0], restored and same\n\n\ndef anf(tt, k):\n    """Moebius transform of GF(2) truth table (len 2^k) -> list of monomials (bitmasks)."""\n    a = np.array(tt, dtype=np.uint8).copy()\n    for t in range(k):\n        step = 1 << t\n        a = a.reshape(-1, 2 * step)\n        a[:, step:] ^= a[:, :step]\n        a = a.reshape(-1)\n    return [m for m in range(1 << k) if a[m]]\n\n\ndef block_anf(nq, body, i, nonzero_q):\n    """nonzero_q: set of qubits possibly nonzero at entry. Returns dict with ANF over input qubits."""\n    j = block_end(body, i)\n    tq = touched(body, i, j)\n    inputs = [q for q in tq if q in nonzero_q]\n    ph, ok = cube_phase(nq, body, i, j, inputs)\n    res = {"i": i, "j": j, "cond": body[i][2], "inputs": inputs, "ok": ok, "tof": block_tof(body, i, j)}\n    if np.all(ph % 4 == 0):\n        mons = anf((ph // 4) % 2, len(inputs))\n        res["anf"] = [tuple(inputs[t] for t in range(len(inputs)) if (m >> t) & 1) for m in mons]\n        res["deg"] = max((len(m) for m in res["anf"]), default=0)\n    else:\n        res["anf"] = None\n        res["phase8"] = ph\n    return res\n', 'scan0.py': '"""Level-0 / level-1 scan: can a conditioned fix-up block\'s phase be paid with fewer Toffolis by spreading it\nover quadratic phase terms (Z / CZ under the same condition bit) at top-level positions inside a window?\n\nThe phase F_B(x) a block applies is computed on a sample of x. The quadratic forms over the live qubits form a\nspace Q(p) that only changes at top-level CCX / CSWAP / HMR (CX, X, SWAP keep it). So F_B can be paid with 0\nToffolis iff F_B lies in the union span of Q(p) over the window [write of the condition bit, B + L events]\n(the bit can be copied to a fresh classical bit if it is overwritten later).\n\nUsage: python scan0.py CIRCUIT.kmx [--before 12] [--after 12] [--nrand 4096] [--min 0.5]\n"""\nimport argparse, json, sys, time\nimport numpy as np\nfrom bitsim import Sim, parse, edge_and_random, TOF, unpack, phase8\nfrom blockpoly import block_end, block_tof\n\nFULL = np.uint64(0xFFFFFFFFFFFFFFFF)\n\n\ndef lowbit_index(row):\n    nz = np.flatnonzero(row)\n    if len(nz) == 0:\n        return -1\n    w = int(row[nz[0]])\n    return int(nz[0]) * 64 + ((w & -w).bit_length() - 1)\n\n\ndef reduce_in_span(M, f, track=False):\n    """Gaussian elimination on rows of M (C x W packed). Returns (in_span, combo) where combo is the\n    set of row indices of M whose XOR equals f (if track and in_span)."""\n    M = M.copy()\n    f = f.copy()\n    C = M.shape[0]\n    if track:\n        T = np.zeros((C, (C + 63) // 64), dtype=np.uint64)\n        for r in range(C):\n            T[r, r // 64] |= np.uint64(1) << np.uint64(r % 64)\n        tf = np.zeros((C + 63) // 64, dtype=np.uint64)\n    for r in range(C):\n        p = lowbit_index(M[r])\n        if p < 0:\n            continue\n        wi, bi = p // 64, np.uint64(p % 64)\n        rest = M[r + 1:]\n        sel = ((rest[:, wi] >> bi) & np.uint64(1)).astype(bool)\n        if sel.any():\n            rest[sel] ^= M[r]\n            if track:\n                T[r + 1:][sel] ^= T[r]\n        if (f[wi] >> bi) & np.uint64(1):\n            f ^= M[r]\n            if track:\n                tf ^= T[r]\n    ok = not f.any()\n    if not track or not ok:\n        return ok, None\n    combo = [r for r in range(C) if (tf[r // 64] >> np.uint64(r % 64)) & np.uint64(1)]\n    return ok, combo\n\n\ndef prepare(circuit, nrand=4096, minimum=0.5):\n    class A: pass\n    a = A(); a.circuit = circuit; a.nrand = nrand; a.min = minimum\n    nq, body = parse(a.circuit)\n    hdr = sum(1 for l in open(a.circuit) if l.startswith(("APPEND", "REGISTER")))\n    xs = edge_and_random(a.nrand)\n    sim = Sim(nq, xs, 1)\n\n    # pass 1: snapshots after top-level span-changing events; block phases; bit-write bookkeeping\n    snaps = []          # (body index, kind, changed qubits, state copy)\n    blocks = []\n    last_write = {}     # bit -> body index of last write (top-level line index of enclosing statement)\n    i = 0\n    n = len(body)\n    t0 = time.time()\n    while i < n:\n        op, args, cond = body[i]\n        if op == "PUSH_CONDITION":\n            j = block_end(body, i)\n            inner = body[i + 1:j]\n            writes = {x[1][-1] for x in inner if x[0] in ("BIT_INVERT", "BIT_STORE0", "BIT_STORE1")}\n            hmr_bits = {x[1][1] for x in inner if x[0] == "HMR"}\n            reads = {x[2] for x in inner if x[2] is not None}\n            tof = block_tof(body, i, j)\n            rec = {"i": i, "j": j, "line": i + hdr + 1, "cond": cond, "tof": tof,\n                   "bitfx": sorted(writes), "cond_write": last_write.get(cond, -1), "snap_before": len(snaps)}\n            if tof >= a.min:\n                saveq, saveph, save8, saveb = sim.q.copy(), sim.ph.copy(), sim.ph8.copy(), dict(sim.b)\n                sim.force[cond] = np.full(sim.W, FULL, dtype=np.uint64)\n                sim.run(body, i, j + 1)\n                del sim.force[cond]\n                d8 = (phase8(sim) - ((4 * unpack(saveph[None, :])[0].astype(np.int64) + save8) % 8)) % 8\n                rec["neutral"] = bool(np.array_equal(saveq, sim.q))\n                rec["gf2"] = bool(np.all(d8 % 4 == 0))\n                if rec["gf2"]:\n                    from bitsim import pack\n                    rec["F"] = pack(((d8 // 4) % 2 == 1)[None, :])[0]\n                sim.q, sim.ph, sim.ph8, sim.b = saveq, saveph, save8, saveb\n                blocks.append(rec)\n            sim.run(body, i, j + 1)\n            for b in writes | hmr_bits:\n                last_write[b] = i\n            i = j + 1\n            continue\n        sim.step(op, args, cond)\n        if op in ("CCX", "CSWAP", "HMR"):\n            ch = [args[2]] if op == "CCX" else ([args[1], args[2]] if op == "CSWAP" else [args[0]])\n            snaps.append((i, op, ch, sim.q.copy()))\n        if op == "HMR":\n            last_write[args[1]] = i\n        if op in ("BIT_INVERT", "BIT_STORE0", "BIT_STORE1"):\n            last_write[args[0]] = i\n            snaps.append((i, op, [], sim.q.copy()))\n        i += 1\n    print(f"pass1 {time.time()-t0:.1f}s, {len(snaps)} snapshots, {len(blocks)} blocks >= {a.min}", flush=True)\n    snap_idx = np.array([s[0] for s in snaps])\n    return nq, body, hdr, xs, sim.W, snaps, snap_idx, blocks\n\n\ndef window(nq, W, snaps, snap_idx, rec, before, after):\n    """rows (list of packed vectors), labels, list of window states [(body idx, state)]."""\n    class A: pass\n    a = A(); a.before = before; a.after = after\n    ones = np.full(W, FULL, dtype=np.uint64)\n    if True:\n        # window: start snapshot = state just after the condition bit\'s last write\n        cw = rec["cond_write"]\n        k_start = int(np.searchsorted(snap_idx, cw, side="right")) - 1  # snapshot at/ before cw\n        # take the snapshot whose index is the last <= cw; if the write was inside a block, use the\n        # last top-level snapshot before the block (state is the same: blocks are state neutral)\n        k_b = rec["snap_before"]  # number of snapshots before block -> events with index < k_b\n        ev_before = [k for k in range(max(k_start + 1, k_b - a.before), k_b) if snaps[k][1] in ("CCX", "CSWAP")]\n        ev_after = [k for k in range(k_b, min(len(snaps), k_b + 3 * a.after)) if snaps[k][1] in ("CCX", "CSWAP")][:a.after]\n        base = snaps[max(k_start, k_b - a.before - 1)][3] if k_start >= 0 else None\n        # base state: the state at the first window position\n        if k_start >= k_b - a.before - 1:\n            base = snaps[k_start][3] if k_start >= 0 else None\n        rows = []\n        labels = []\n        states = []\n        rows.append(ones); labels.append(("const",))\n        if base is not None:\n            states.append((snaps[k_start][0] if k_start >= k_b - a.before - 1 else snaps[k_b - a.before - 1][0], base))\n            live = [q for q in range(nq) if base[q].any()]\n            for x in range(len(live)):\n                rows.append(base[live[x]]); labels.append(("Z", "start", live[x]))\n                for y in range(x + 1, len(live)):\n                    rows.append(base[live[x]] & base[live[y]]); labels.append(("CZ", "start", live[x], live[y]))\n        for k in ev_before + ev_after:\n            st = snaps[k][3]\n            states.append((snaps[k][0], st))\n            for t in snaps[k][2]:\n                rows.append(st[t]); labels.append(("Z", snaps[k][0], t))\n                for q in range(nq):\n                    if q != t and st[q].any():\n                        rows.append(st[t] & st[q]); labels.append(("CZ", snaps[k][0], t, q))\n        return rows, labels, states, len(ev_before), len(ev_after)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("circuit")\n    ap.add_argument("--before", type=int, default=12)\n    ap.add_argument("--after", type=int, default=12)\n    ap.add_argument("--nrand", type=int, default=4096)\n    ap.add_argument("--min", type=float, default=0.5)\n    ap.add_argument("--out", default=None)\n    a = ap.parse_args()\n    nq, body, hdr, xs, W, snaps, snap_idx, blocks = prepare(a.circuit, a.nrand, a.min)\n    results = []\n    for rec in blocks:\n        tag = f"line {rec[\'line\']} cond {rec[\'cond\']} tof {rec[\'tof\']}"\n        if not rec.get("neutral") or not rec.get("gf2"):\n            print(tag, "SKIP neutral", rec.get("neutral"), "gf2", rec.get("gf2"))\n            continue\n        if rec["bitfx"]:\n            print(tag, "SKIP bit side effects", rec["bitfx"])\n            continue\n        F = rec["F"]\n        if not F.any():\n            print(tag, "ZERO PHASE (block removable!)")\n            results.append({**{k: v for k, v in rec.items() if k != "F"}, "verdict": "zero"})\n            continue\n        rows, labels, states, nb, na = window(nq, W, snaps, snap_idx, rec, a.before, a.after)\n        ev_before, ev_after = [0] * nb, [0] * na\n        M = np.array(rows)\n        t1 = time.time()\n        ok, _ = reduce_in_span(M, F)\n        r = {**{k: v for k, v in rec.items() if k != "F"}, "cols": len(rows), "verdict": "LEVEL0" if ok else "no",\n             "ev_before": len(ev_before), "ev_after": len(ev_after)}\n        print(tag, "cols", len(rows), "ev", len(ev_before), len(ev_after), "->", r["verdict"], f"{time.time()-t1:.1f}s", flush=True)\n        results.append(r)\n    if a.out:\n        json.dump(results, open(a.out, "w"), indent=1, default=str)\n\n\nif __name__ == "__main__":\n    main()\n', 'level2.py': '"""Level-2 scan: can a fix-up block\'s phase F be paid with TWO conditioned ANDs?\n  r1 = L1*L2 (L weight <= 2 forms over R), r2 = M1*M3 (M = form over R plus optional r1),\n  F in span( M_window  +  {r1*q}  +  {r2*q} ),  q over live qubits, const and r1.\nAll product forms are evaluated at the block\'s entry state. Membership via random parity checks of span(M_window)\n(K bits), then a projection that kills span{r1*q} (K2 bits), then batched elimination; hits re-checked on full vectors.\nUsage: python level2.py CIRCUIT.kmx --lines a,b [--rmax 9] [--min 1.0]\n"""\nimport argparse, itertools, time\nimport numpy as np\nfrom bitsim import unpack\nfrom blockpoly import touched, block_end, cube_phase, anf\nfrom scan0 import prepare, window, reduce_in_span, FULL\nfrom level1 import null_checks, syndromes, batched_member\n\nrng = np.random.default_rng(11)\n\n\ndef to_float_bits(S, K):\n    """packed syndromes (N, K/64) uint64 -> (N, K) float32 0/1"""\n    N = S.shape[0]\n    out = np.zeros((N, K), dtype=np.float32)\n    for k in range(K):\n        out[:, k] = ((S[:, k // 64] >> np.uint64(k % 64)) & np.uint64(1)).astype(np.float32)\n    return out\n\n\ndef pack_float_bits(B):\n    N, K = B.shape\n    out = np.zeros((N, (K + 63) // 64), dtype=np.uint64)\n    Bi = B.astype(np.uint64)\n    for k in range(K):\n        out[:, k // 64] |= Bi[:, k] << np.uint64(k % 64)\n    return out\n\n\ndef nullspace_rows(G):\n    """G (m, K) 0/1 -> basis (d, K) of {p : G p = 0} over GF(2)."""\n    G = (G.astype(np.uint8) & 1).copy()\n    m, K = G.shape\n    piv = []\n    r = 0\n    for c in range(K):\n        rows = np.flatnonzero(G[r:, c]) + r if r < m else []\n        if len(rows) == 0:\n            continue\n        p = rows[0]\n        G[[r, p]] = G[[p, r]]\n        sel = np.flatnonzero(G[:, c]); sel = sel[sel != r]\n        G[sel] ^= G[r]\n        piv.append(c); r += 1\n        if r == m:\n            break\n    free = [c for c in range(K) if c not in set(piv)]\n    basis = np.zeros((len(free), K), dtype=np.uint8)\n    for t, f in enumerate(free):\n        basis[t, f] = 1\n        for i, c in enumerate(piv):\n            basis[t, c] = G[i, f]\n    return basis\n\n\ndef polymul(p, q):\n    out = {}\n    for a in p:\n        for b in q:\n            m = a | b\n            out[m] = out.get(m, 0) ^ 1\n    return frozenset(m for m, v in out.items() if v)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("circuit")\n    ap.add_argument("--lines", default=None)\n    ap.add_argument("--min", type=float, default=1.0)\n    ap.add_argument("--max", type=float, default=99)\n    ap.add_argument("--rmax", type=int, default=9)\n    ap.add_argument("--before", type=int, default=12)\n    ap.add_argument("--after", type=int, default=12)\n    ap.add_argument("--K", type=int, default=256)\n    ap.add_argument("--K2", type=int, default=128)\n    a = ap.parse_args()\n    nq, body, hdr, xs, W, snaps, snap_idx, blocks = prepare(a.circuit, 4096, a.min)\n    want = None if a.lines is None else {int(v) for v in a.lines.split(",")}\n    # entry states of blocks\n    entry = {}\n    from bitsim import Sim\n    sim = Sim(nq, xs, 1)\n    targets = {rec["i"] for rec in blocks}\n    sim.run(body, hook=lambda i, s: entry.__setitem__(i, s.q.copy()) if i in targets and len(s.stack) == 1 else None)\n    for rec in blocks:\n        if want is not None and rec["line"] not in want:\n            continue\n        if rec["tof"] > a.max:\n            continue\n        tag = f"line {rec[\'line\']} cond {rec[\'cond\']} tof {rec[\'tof\']}"\n        if not rec.get("neutral") or not rec.get("gf2") or rec["bitfx"]:\n            print(tag, "SKIP", flush=True); continue\n        t0 = time.time()\n        st = entry[rec["i"]]\n        F = rec["F"]\n        rows, labels, states, nb, na = window(nq, W, snaps, snap_idx, rec, a.before, a.after)\n        M = np.array(rows)\n        H = null_checks(M, a.K, rng)\n        live = [q for q in range(nq) if st[q].any()]\n        # relevant set: qubits in degree>=3 ANF monomials of the block phase (cube over its inputs)\n        j = rec["j"]\n        inputs = [q for q in touched(body, rec["i"], j) if q in live]\n        ph, ok = cube_phase(nq, body, rec["i"], j, inputs)\n        mons = anf((ph // 4) % 2, len(inputs))\n        cnt = {}\n        for m in mons:\n            if bin(m).count("1") >= 3:\n                for t in range(len(inputs)):\n                    if (m >> t) & 1:\n                        cnt[inputs[t]] = cnt.get(inputs[t], 0) + 1\n        R = sorted(cnt, key=lambda q: -cnt[q])[: a.rmax]\n        nR = len(R)\n        Q = live + [None]\n        # monomial syndromes sigma(x_S * q), |S| <= 4\n        subsets = [m for m in range(1 << nR) if bin(m).count("1") <= 4]\n        sidx = {m: t for t, m in enumerate(subsets)}\n        V = []\n        for m in subsets:\n            base = np.full(W, FULL, dtype=np.uint64)\n            for t in range(nR):\n                if (m >> t) & 1:\n                    base = base & st[R[t]]\n            for q in Q:\n                V.append(base if q is None else base & st[q])\n        Sy = to_float_bits(syndromes(np.array(V), H), a.K).reshape(len(subsets), len(Q), a.K)\n        sF = to_float_bits(syndromes(F[None, :], H), a.K)[0]\n        forms = [frozenset([1 << t]) for t in range(nR)] + [frozenset([1 << s, 1 << t]) for s, t in itertools.combinations(range(nR), 2)]\n        fpairs = [(x, y) for x in range(len(forms)) for y in range(x, len(forms))]\n        # A[pair, q] = sigma(l1 l3 q)\n        def psyn(poly, qi):\n            acc = np.zeros(a.K, dtype=np.float32)\n            for m in poly:\n                acc += Sy[sidx[m], qi]\n            return acc % 2\n        Aall = np.zeros((len(fpairs), len(Q), a.K), dtype=np.float32)\n        for t, (x, y) in enumerate(fpairs):\n            pp = polymul(forms[x], forms[y])\n            for m in pp:\n                Aall[t] += Sy[sidx[m]]\n        Aall %= 2\n        hits = []\n        n_sys = 0\n        for (u, v) in fpairs:\n            r1 = polymul(forms[u], forms[v])\n            if not r1 or all(bin(m).count("1") < 2 for m in r1):\n                continue  # affine product: no AND\n            G1 = np.zeros((len(Q), a.K), dtype=np.float32)\n            for m in r1:\n                G1 += Sy[sidx[m]]\n            G1 %= 2\n            Nb = nullspace_rows(G1)\n            if Nb.shape[0] < a.K2:\n                continue\n            P = (rng.integers(0, 2, size=(a.K2, Nb.shape[0])).astype(np.float32) @ Nb.astype(np.float32)) % 2\n            proj = lambda X: (X @ P.T) % 2\n            sF1 = proj(sF[None, :])[0]\n            if not sF1.any():\n                hits.append(("level1-like", forms[u], forms[v])); continue\n            A1 = proj(Aall.reshape(-1, a.K)).reshape(len(fpairs), len(Q), a.K2)\n            # B[f, q] = sigma(l * r1 * q); C[pair] = sigma(r1 l1 l3)\n            B = np.zeros((len(forms), len(Q), a.K), dtype=np.float32)\n            for f in range(len(forms)):\n                for m in polymul(forms[f], r1):\n                    B[f] += Sy[sidx[m]]\n            B = proj((B % 2).reshape(-1, a.K)).reshape(len(forms), len(Q), a.K2)\n            Cc = np.zeros((len(fpairs), a.K), dtype=np.float32)\n            for t, (x, y) in enumerate(fpairs):\n                for m in polymul(polymul(forms[x], forms[y]), r1):\n                    if bin(m).count("1") <= 4:\n                        Cc[t] += Sy[sidx[m], len(Q) - 1]\n                    else:\n                        Cc[t] += np.nan\n            Cc = np.nan_to_num(Cc % 2, nan=0.0)\n            Cc = proj(Cc)\n            gens = []\n            meta = []\n            fx = np.array([x for x, y in fpairs]); fy = np.array([y for x, y in fpairs])\n            for c1 in (0, 1):\n                for c3 in (0, 1):\n                    g = A1 + c3 * B[fx] + c1 * B[fy]  # (pairs, Q, K2)\n                    gq = Cc + c3 * B[fx, len(Q) - 1] + c1 * B[fy, len(Q) - 1]\n                    gens.append(np.concatenate([g, gq[:, None, :]], axis=1) % 2)\n                    meta += [(t, c1, c3) for t in range(len(fpairs))]\n            G = np.concatenate(gens, axis=0)\n            n_sys += G.shape[0]\n            Gp = pack_float_bits(G.reshape(-1, a.K2)).reshape(G.shape[0], G.shape[1], -1)\n            okm = batched_member(Gp, pack_float_bits(sF1[None, :])[0])\n            for t in np.flatnonzero(okm):\n                hits.append((forms[u], forms[v], meta[t]))\n        def fmt(f):\n            return "+".join("q%d" % R[b] for m in f for b in range(nR) if (m >> b) & 1)\n        shown = [(fmt(h[0]) if not isinstance(h[0], str) else h[0], fmt(h[1]) if not isinstance(h[1], str) else fmt(h[2]), h[2] if not isinstance(h[0], str) else "") for h in hits[:4]]\n        print(tag, "R", R, "systems", n_sys, "hits", len(hits), shown, f"{time.time()-t0:.0f}s", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n'}
