LINES = "22006,22585,23108,23639,24204,24756,25304,25828,26368,26891,27405,27921,28428,28869,34070,34601,35139,50997".split(",")
def job(l):
    p = subprocess.run([sys.executable, "-u", "level2.py", "inv.kmx", "--lines", l, "--min", "1.5", "--max", "1.5"], cwd=T, capture_output=True, text=True)
    out = p.stdout[-3000:] + p.stderr[-1500:]
    (W / f"l2_{l}.log").write_text(out); print(l, out.strip().splitlines()[-1] if out.strip() else "", flush=True)
with ThreadPoolExecutor(max_workers=os.cpu_count() or 4) as ex: list(ex.map(job, LINES))
print("done", flush=True)
